<script lang="ts">
 import {createEventDispatcher} from 'svelte';import {authorizationUrl,validShopDomain,type ProviderSetup,type Authorization,type ConnectionOptions} from './automations-client';import './automations.css';
 export let providerId:string;export let providerName:string;export let requestedScopes:string[]=[];export let setup:ProviderSetup|null=null;export let canManage=false;export let busy=false;export let authorization:Authorization|null=null;
 const dispatch=createEventDispatcher<{connect:{providerId:string}&ConnectionOptions;refresh:void}>();let shopDomain='',seen='';
 $: setupKey=providerId+':'+(setup?.setupRevision??'')+':'+(setup?.shopDomain||'');
 $: if(seen!==setupKey){seen=setupKey;shopDomain=setup?.shopDomain||'';}
 $: needsShop=providerId==='shopify'&&!!setup&&((setup.missingFields.includes('shopDomain')||setup.missingFields.includes('SHOPIFY_SHOP_DOMAIN'))||setup.status==='SHOP_DOMAIN_REQUIRED');
 $: domainValid=!needsShop||validShopDomain(shopDomain);
 function connect(){if(!setup||!canManage||busy||!domainValid)return;dispatch('connect',{providerId,...(providerId==='shopify'&&shopDomain?{shopDomain,expectedSetupRevision:setup.setupRevision}:{})});}
</script>
<div class="starli-automations connection-card" aria-label={providerName+' connection'}><div class="sa-connect"><div class="sa-service-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="20" height="20" fill="none"><path d="m9 15 6-6m-9 4-2 2a4.24 4.24 0 0 0 6 6l3-3m-2-12 2-2a4.24 4.24 0 0 1 6 6l-3 3" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg></div><div><h4>Connect {providerName}</h4><p class="sa-muted">This account is shared with authorized bots in your company. Your original conversation and setup are preserved.</p></div></div>{#if requestedScopes.length}<div class="sa-permissions"><strong>Requested permissions</strong>{#each requestedScopes as scope}<span>{scope}</span>{/each}</div>{/if}
 {#if !setup}<p class="sa-warning" role="status">Connection setup status is unavailable. Refresh to check this company’s secure sign-in.</p><button disabled={busy} on:click={()=>dispatch('refresh')}>Check connection setup</button>{:else}
 {#if needsShop}<label class="sa-label">Shopify store domain<input class="sa-input" bind:value={shopDomain} placeholder="your-store.myshopify.com" autocomplete="off" autocapitalize="none" spellcheck={false} disabled={busy||!canManage}/></label><p class="sa-muted">Use the store’s exact myshopify.com domain, without https:// or a path.</p>{#if shopDomain&&!domainValid}<p class="sa-warning" role="alert">Enter a lowercase store-name.myshopify.com domain.</p>{/if}{:else if setup.shopDomain}<p class="sa-muted">Store: {setup.shopDomain}</p>{/if}
 {#if setup.status==='APP_CONFIGURATION_REQUIRED'}<p class="sa-warning" role="status">{providerName} sign-in is not configured for this company yet. Your setup is saved. Contact your company administrator.</p>{/if}
 {#if authorization?.status==='AUTHORIZATION_REQUIRED'&&authorizationUrl(authorization.authorizationUrl)}<div class="sa-actions"><a class="sa-primary sa-link" href={authorizationUrl(authorization.authorizationUrl)||undefined} target="_blank" rel="noopener noreferrer">Authorize {providerName} ↗</a><button disabled={busy} on:click={()=>dispatch('refresh')}>I’ve finished connecting</button></div><p class="sa-muted">Review the exact account and permissions on {providerName}’s consent screen. Return to Starli after approving.</p>{:else if setup.status!=='APP_CONFIGURATION_REQUIRED'||needsShop}<button class="sa-primary" disabled={busy||!canManage||!domainValid} on:click={connect}>{busy?'Checking…':setup.status==='APP_CONFIGURATION_REQUIRED'?'Save store domain':'Continue to '+providerName}</button>{/if}
 {#if authorization?.status==='SETUP_UNAVAILABLE'&&setup.status!=='APP_CONFIGURATION_REQUIRED'}<p class="sa-warning" role="status">Secure sign-in could not start. Your setup remains saved; refresh its connection status before trying again.</p>{/if}{/if}
</div>
